/* pkg_conformance.cpp — C++ reader conformance against the Rust-written
 * golden fixture (tests/pkg/fixtures/sample.tplc generated by
 * `tplc-pkg gen`). Proves cross-implementation byte compatibility:
 * same container, same hashes, same LAYD/MIGD decodes.
 * SPDX-License-Identifier: Apache-2.0 OR MPL-2.0 */

#include <tplc/pkg/Package.hpp>
#include <tplc/pkg/Sha256.hpp>
#include <tplc/tplc_pkg.h>

#include <cstdio>
#include <cstring>
#include <vector>

static int g_checks = 0, g_fails = 0;
#define CHECK(cond, label) do { \
    g_checks++; \
    if (!(cond)) { \
        g_fails++; \
        std::printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, label); \
    } \
} while (0)

/* LAYD decode check values mirror the fixture generator. */
struct LaydHeaderC { uint32_t magic, version, region_count, pad; uint64_t total; };
struct LaydRegionC { uint8_t kind, pad[3]; uint32_t align; uint64_t off, size; };

int main(int argc, char** argv) {
    const char* fixPath = argc > 1 ? argv[1] : "tests/pkg/fixtures/sample.tplc";

    /* ---- SHA-256 self-test (FIPS 180-4 vectors) ---- */
    {
        uint8_t d[32];
        tplc::Sha256::hash("abc", 3, d);
        static const uint8_t want[32] = {
            0xba,0x78,0x16,0xbf,0x8f,0x01,0xcf,0xea,
            0x41,0x41,0x40,0xde,0x5d,0xae,0x22,0x23,
            0xb0,0x03,0x61,0xa3,0x96,0x17,0x7a,0x9c,
            0xb4,0x10,0xff,0x61,0xf2,0x00,0x15,0xad};
        CHECK(std::memcmp(d, want, 32) == 0, "sha256('abc')");
        tplc::Sha256::hash("", 0, d);
        static const uint8_t wantEmpty[32] = {
            0xe3,0xb0,0xc4,0x42,0x98,0xfc,0x1c,0x14,
            0x9a,0xfb,0xf4,0xc8,0x99,0x6f,0xb9,0x24,
            0x27,0xae,0x41,0xe4,0x64,0x9b,0x93,0x4c,
            0xa4,0x95,0x99,0x1b,0x78,0x52,0xb8,0x55};
        CHECK(std::memcmp(d, wantEmpty, 32) == 0, "sha256('')");
    }

    /* ---- golden fixture via open() ---- */
    auto res = tplc::Package::open(fixPath);
    if (!res.ok()) {
        std::printf("FATAL: cannot parse fixture %s: %d %s\n",
                    fixPath, res.st.code, res.st.msg.c_str());
        return 1;
    }
    tplc::Package pkg = std::move(res.value);

    CHECK(pkg.header().format_version == 1, "format v1");
    CHECK(pkg.uuidStr() == "018c2f7e-9a3b-7c4d-8e5f-1234567890ab", "uuid");
    CHECK(pkg.toc().size() == 8, "8 sections");
    CHECK(pkg.header().total_size == pkg.buffer().size(), "total_size");

    /* sorted TOC */
    uint32_t prev = 0; bool sorted = true;
    for (auto& e : pkg.toc()) {
        if (e.section_type <= prev) sorted = false;
        prev = e.section_type;
    }
    CHECK(sorted, "toc sorted");

    /* section contents — byte-identical to what the Rust writer encoded */
    tplc::PkgSection s;
    CHECK(pkg.section(TPLC_SEC_MANIFEST, s), "manifest present");
    CHECK(s.size > 0 && std::strstr((const char*)s.data,
                                    "tplc.manifest.v1") != nullptr,
          "manifest schema");
    CHECK(pkg.manifestJson().find("fixture_pkg") != std::string::npos,
          "manifest json");

    CHECK(pkg.section(TPLC_SEC_IR_BITCODE, s), "ir present");
    CHECK(s.size == 19 && std::memcmp(s.data, "FAKE-BC-PLACEHOLDER", 19) == 0,
          "ir content");
    CHECK(pkg.section(TPLC_SEC_TARGET_OBJ, s) && s.size == 4 &&
          s.data[0] == 0x7f && s.data[1] == 'E', "target_obj");
    CHECK(pkg.section(TPLC_SEC_SYMMAP, s) &&
          std::memcmp(s.data, "SMAP-STUB", 9) == 0, "symmap content");

    /* LAYD decode (C-side struct reads of Rust-encoded bytes) */
    CHECK(pkg.section(TPLC_SEC_LAYOUT_DESC, s), "layd present");
    {
        LaydHeaderC lh;
        std::memcpy(&lh, s.data, sizeof lh);
        CHECK(lh.magic == 0x4459414Cu, "layd magic");
        CHECK(lh.region_count == 2, "layd regions");
        CHECK(lh.total == 64, "layd total");
        LaydRegionC r1;
        std::memcpy(&r1, s.data + sizeof lh + sizeof(LaydRegionC), sizeof r1);
        CHECK(r1.kind == 3 && r1.off == 48 && r1.size == 16, "retain region");
    }

    /* required-for-load set */
    CHECK(pkg.validateForLoad(false).ok(), "validate_for_load");
    CHECK(pkg.validateForLoad(true).ok(), "validate_for_load stripped");

    /* ---- adversarial: tampered copies of the same fixture ---- */
    {
        std::vector<uint8_t> buf = pkg.buffer();

        /* payload tamper → HASH_CONTENT (offset 420 = inside manifest,
         * which starts at header_size 416; padding bytes are not hashed) */
        buf[420] ^= 0xFF;
        auto bad = tplc::Package::parse(buf.data(), buf.size());
        CHECK(!bad.ok() && bad.st.code == TPLC_E_PKG_HASH_CONTENT,
              "payload tamper");
        buf = pkg.buffer();

        /* header field tamper (flags) → HASH_HEADER */
        buf[20] ^= 1;
        bad = tplc::Package::parse(buf.data(), buf.size());
        CHECK(!bad.ok() && bad.st.code == TPLC_E_PKG_HASH_HEADER,
              "header tamper");
        buf = pkg.buffer();

        /* TOC tamper (aux byte of entry 1) → HASH_CONTENT (D-IMPL-13) */
        buf[TPLC_PKG_HEADER_FIXED + 32 + 28] ^= 1;
        bad = tplc::Package::parse(buf.data(), buf.size());
        CHECK(!bad.ok() && bad.st.code == TPLC_E_PKG_HASH_CONTENT,
              "toc tamper");
        buf = pkg.buffer();

        /* magic tamper → MAGIC */
        buf[0] = 'X';
        bad = tplc::Package::parse(buf.data(), buf.size());
        CHECK(!bad.ok() && bad.st.code == TPLC_E_PKG_MAGIC, "bad magic");
    }

    std::printf("pkg_conformance: %d checks, %d failures\n",
                g_checks, g_fails);
    return g_fails ? 1 : 0;
}
